var MM_COLORS=['R','G','B','Y','O','P'];
function mmSecret(n, colors){ colors=colors||MM_COLORS; n=n||4; var s=[]; for(var i=0;i<n;i++) s.push(colors[Math.floor(Math.random()*colors.length)]); return s; }
function mmScore(secret, guess){
  var black=0, white=0; var sU=new Array(secret.length).fill(false), gU=new Array(guess.length).fill(false);
  for(var i=0;i<secret.length;i++){ if(guess[i]===secret[i]){ black++; sU[i]=true; gU[i]=true; } }
  for(var i=0;i<guess.length;i++){ if(gU[i]) continue; for(var j=0;j<secret.length;j++){ if(!sU[j] && guess[i]===secret[j]){ white++; sU[j]=true; gU[i]=true; break; } } }
  return {black:black, white:white};
}
var EXPORTS={mmSecret:mmSecret,mmScore:mmScore,MM_COLORS:MM_COLORS};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MastermindForgePure = EXPORTS; }
